function safeStorage(name){
 try{const store=window[name];store.getItem('__miros_storage_probe__');return store;}
 catch(error){const values=new Map();return{getItem:key=>values.has(String(key))?values.get(String(key)):null,setItem:(key,value)=>values.set(String(key),String(value)),removeItem:key=>values.delete(String(key)),clear:()=>values.clear()};}
}
