function setWallpaperElement(element,value,custom=''){
 if(!element)return;
 element.style.backgroundColor='#10131d';
 if(custom){element.style.backgroundImage=`url(\"${String(custom).replace(/\"/g,'%22')}\")`;element.style.backgroundSize='cover';element.style.backgroundPosition='center';element.style.backgroundRepeat='no-repeat';return;}
 if(WALLPAPER_ASSETS[value]){element.style.backgroundImage=`url(\"${WALLPAPER_ASSETS[value]}\")`;element.style.backgroundSize='cover';element.style.backgroundPosition='center';element.style.backgroundRepeat='no-repeat';return;}
 element.style.backgroundImage='';element.style.background=WALLPAPER_BACKGROUNDS[value]||WALLPAPER_BACKGROUNDS.Aurora;
}
