function cleanCustomWebApps(rows){
 if(!Array.isArray(rows))return[];
 const clean=[];
 for(const row of rows){
  if(!row||typeof row!=='object')continue;
  const name=String(row.name||'').trim().slice(0,48);
  let url='';try{const parsed=new URL(String(row.url||''));if(!['http:','https:'].includes(parsed.protocol)||parsed.username||parsed.password)continue;url=parsed.href;}catch(e){continue;}
  if(!name)continue;
  const id=String(row.id||'').replace(/[^a-z0-9-]/gi,'').slice(0,72);
  if(!id||APPS.some(app=>app.id===id)||clean.some(app=>app.id===id))continue;
  clean.push({id,name,icon:String(row.icon||'🌐').replace(/[<>&\"'`]/g,'').slice(0,8)||'🌐',category:String(row.category||'Web Apps').trim().slice(0,32)||'Web Apps',description:String(row.description||'Custom website app added to MirStore.').trim().slice(0,140),type:'web',url,installed:false,customWebApp:true});
 }
 return clean;
}
