 state.desktopShortcuts=[...new Set((JSON.parse(localStorage.getItem(DESKTOP_SHORTCUTS_KEY)||'null')||['file-manager','browser','notes','mircode-studio','settings']).map(id=>id==='app-store'?'mirstore':id))].filter(id=>APPS.some(a=>a.id===id)&&state.installed.includes(id));
