let soundContext=null;
let startupSoundPending=false;
const SOUND_PATTERNS={
 click:[[620,.035,.34]],open:[[440,.075,.42],[660,.095,.34]],close:[[620,.065,.38],[390,.075,.27]],
 minimize:[[520,.055,.34],[360,.075,.24]],restore:[[360,.06,.28],[560,.09,.38]],maximize:[[470,.06,.3],[700,.09,.35]],
 notification:[[660,.10,.35],[880,.13,.28]],startup:[[392,.16,.26],[494,.17,.3],[587,.19,.34],[784,.3,.3]],
 success:[[523,.09,.28],[659,.1,.3],[784,.16,.32]],error:[[260,.1,.35],[196,.13,.3]],keyboard:[[540,.022,.22]],preview:[[523,.11,.32],[659,.12,.32],[784,.18,.32]]
};
function playUISound(type='click'){
 const key=type==='preview'?'':type==='notification'?'notificationSound':type==='startup'?'startupSound':type==='keyboard'?'keyboardSound':'uiSounds';
 if(state.settings.muteAll||Number(state.settings.soundVolume??60)<=0||(key&&!state.settings[key]))return;
 const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return;
 try{
  if(!soundContext||soundContext.state==='closed')soundContext=new AudioCtx();
  const schedule=()=>{
   if(!soundContext||soundContext.state!=='running')return;
   const ctx=soundContext,theme=state.settings.soundTheme||'MirOS';
   const wave=theme==='Classic'?'triangle':'sine';
   const volume=Math.max(0,Math.min(1,Number(state.settings.soundVolume??60)/100))*.055;
   const pattern=SOUND_PATTERNS[type]||SOUND_PATTERNS.click;const start=ctx.currentTime+.006;
   pattern.forEach(([frequency,duration,level],index)=>{
    const osc=ctx.createOscillator(),gain=ctx.createGain();
    const oneUi=theme==='One UI';osc.type=wave;osc.frequency.setValueAtTime(oneUi?frequency*.92:frequency,start+index*.075);
    const t=start+index*.075,peak=Math.max(.0001,volume*level);
    gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(peak,t+.008);gain.gain.exponentialRampToValueAtTime(.0001,t+duration);
    osc.connect(gain);gain.connect(ctx.destination);osc.start(t);osc.stop(t+duration+.015);
   });
  };
  if(soundContext.state==='suspended')soundContext.resume().then(schedule).catch(()=>{});else schedule();
 }catch(e){}
}
function unlockMirOSSounds(){
 const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return;
 try{
  if(!soundContext||soundContext.state==='closed')soundContext=new AudioCtx();
  const ready=soundContext.state==='suspended'?soundContext.resume():Promise.resolve();
  ready.then(()=>{if(startupSoundPending){startupSoundPending=false;playUISound('startup');}}).catch(()=>{});
 }catch(e){}
}
