function unpinTaskbarApp(id){state.pinnedApps=state.pinnedApps.filter(x=>x!==id);persistList(TASKBAR_PINS_KEY,state.pinnedApps);renderDesktop();toast(`${appById(id).name} unpinned from taskbar.`);}
async function createDesktopShortcut(){const id=await inputModal('Create desktop shortcut','Installed app ID or name','e.g. notes');if(!id)return;const app=APPS.find(a=>a.id===id||a.name.toLowerCase()===id.toLowerCase());if(!app){toast('App not found. Install it from MirStore first.');return;}if(!state.installed.includes(app.id)){toast('Install this app from MirStore before creating a shortcut.');return;}addDesktopShortcut(app.id);}
function sortDesktop(order='name'){const get=id=>appById(id);state.desktopShortcuts.sort((a,b)=>{const x=get(a),y=get(b);if(order==='type'){const tx=(x.custom||x.url||EXTERNAL_WEB_APPS[x.id])?'Website app':'MirOS app',ty=(y.custom||y.url||EXTERNAL_WEB_APPS[y.id])?'Website app':'MirOS app';return tx.localeCompare(ty)||x.name.localeCompare(y.name);}if(order==='category')return x.category.localeCompare(y.category)||x.name.localeCompare(y.name);if(order==='date')return (APPS.indexOf(y)||0)-(APPS.indexOf(x)||0);return x.name.localeCompare(y.name);});state.desktopPositions={};persistList(DESKTOP_SHORTCUTS_KEY,state.desktopShortcuts);persistList(DESKTOP_POSITIONS_KEY,state.desktopPositions);renderDesktop();}

