  let pattern='';renderPatternPad($('#lockPatternPad',root),v=>pattern=v);$('#lockPatternSubmit',root).onclick=async()=>{if(!pattern||pattern.split('-').length<4){lockAuthFailed('Connect at least four points.');return;}if(await verifyLockSecret(pattern))unlockLockScreen();else lockAuthFailed('That pattern is incorrect. Try again.');};return;
