  root.innerHTML='<div class="lock-fingerprint-caption">Tap the fingerprint icon to open MirOS.</div><button type="button" id="lockFingerprintButton" class="lock-fingerprint-button tap-unlock-fingerprint" aria-label="Tap fingerprint icon to unlock MirOS"><svg viewBox="0 0 48 48" aria-hidden="true" focusable="false"><path d="M6 23a18 18 0 0 1 36 0M11 23a13 13 0 0 1 26 0c0 8-1.5 14-4 19M16 23a8 8 0 0 1 16 0c0 7-1 12-2.5 16M24 23c0 8-.4 13-1.5 18M8 28c.5 5 2 9 4 12M40 28c-.5 5-2 9-4 12" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg></button><div class="lock-auth-error" id="lockAuthError" aria-live="polite"></div><div class="lock-method-caption">Tap-to-unlock mode. It does not check for a physical fingerprint sensor.</div>';
