function focusWindow(id){const win=state.windows.find(w=>w.id===id);if(!win)return;if(win.desktopId!==state.currentDesktop)switchDesktop(win.desktopId);win.minimized=false;win.z=++state.z;const el=document.querySelector(`[data-window-id="${id}"]`);if(el){el.classList.remove('minimized');el.style.zIndex=win.z;}renderDesktop();}
function minimizeWindow(id,min=true){const win=state.windows.find(w=>w.id===id);if(!win)return;playUISound(min?'minimize':'restore');win.minimized=min;const el=document.querySelector(`[data-window-id="${id}"]`);if(el)el.classList.toggle('minimized',min);renderDesktop();}
function applyMaximizedGeometry(el){Object.assign(el.style,{left:'0px',top:'0px',width:'100vw',height:'100vh',borderRadius:'0px'});el.classList.add('maximized');}
