function openApp(id,arg){id=normalizeAppId(id);playUISound('open');let app=appById(id);const externalUrl=externalWebUrl(id,app);if(externalUrl){if(!state.installed.includes(id)){state.installed.push(id);saveInstalled();}openWebApp(id,externalUrl);return;}if(!state.installed.includes(id)&&id!=='settings'&&id!=='mirstore'&&id!=='app-store'){state.installed.push(id);saveInstalled();}const existing=state.windows.find(w=>w.appId===id);if(existing){if(existing.minimized)minimizeWindow(existing.id,false);focusWindow(existing.id);return;}
 const win={id:uid(),appId:id,x:Math.max(12,Math.min(innerWidth-790,90+state.windows.length*28)),y:Math.max(48,Math.min(innerHeight-640,72+state.windows.length*25)),width:Math.min(800,innerWidth-32),height:Math.min(590,innerHeight-130),z:++state.z,minimized:false,maximized:!!state.settings.fullscreenDefault,desktopId:state.currentDesktop};state.windows.push(win);const el=document.createElement('section');el.className='os-window';el.dataset.windowId=win.id;el.style.cssText=`left:${win.x}px;top:${win.y}px;width:${win.width}px;height:${win.height}px;z-index:${win.z}`;el.innerHTML=`<header class="window-titlebar"><span class="window-app-icon">${app.icon}</span><span class="window-title">${esc(app.name)}</span><div class="window-controls"><button class="window-control" data-win="min" title="Minimize">−</button><button class="window-control" data-win="max" title="Maximize">□</button><button class="window-control close" data-win="close" title="Close">×</button></div></header><div class="window-content" id="content-${win.id}"><div class="empty-state"><div class="empty-icon">${app.icon}</div><strong>Opening ${esc(app.name)}…</strong></div></div><div class="window-resize"></div>`;$('#windowLayer').append(el);el.querySelector('[data-win="min"]').onclick=()=>minimizeWindow(win.id);el.querySelector('[data-win="max"]').onclick=()=>maximizeWindow(win.id);el.querySelector('[data-win="close"]').onclick=()=>closeWindow(win.id);el.querySelector('.window-titlebar').ondblclick=e=>{if(!e.target.closest('.window-controls'))maximizeWindow(win.id);};makeDraggable(el,win);if(win.maximized){win.restore={x:win.x,y:win.y,width:win.width,height:win.height};applyMaximizedGeometry(el);}renderDesktop();renderApp(id,$(`#content-${win.id}`),arg,win.id).catch(err=>{$(`#content-${win.id}`).innerHTML=`<div class="empty-state"><strong>App could not open</strong><p>${esc(err.message||'Unexpected error')}</p></div>`;});
}

