  if(id==='base64-tools'){bind('toolEncode',()=>{try{output.value=btoa(Array.from(new TextEncoder().encode(input()),b=>String.fromCharCode(b)).join(''));}catch(e){output.value=e.message;}});bind('toolDecode',()=>{try{output.value=new TextDecoder().decode(Uint8Array.from(atob(input()),c=>c.charCodeAt(0)));}catch(e){output.value='Invalid Base64 input.';}});}
