  if(id==='diff-checker')bind('toolRun',()=>{const a=$('#toolA',root).value.split(/\r?\n/),b=$('#toolB',root).value.split(/\r?\n/),n=Math.max(a.length,b.length),lines=[];for(let i=0;i<n;i++){if(a[i]===b[i])lines.push('  '+(a[i]??''));else{if(a[i]!==undefined)lines.push('- '+a[i]);if(b[i]!==undefined)lines.push('+ '+b[i]);}}output.textContent=lines.join('\n')||'No differences.';});
